css:
@supports not ((backdrop-filter: blur(1px)) or (-webkit-backdrop-filter: blur(1px))) {
  .css-liquid-glass::before { background: rgb(var(--lg-tint-rgb) / var(--lg-fallback-alpha)); }
}
@media (prefers-reduced-transparency: reduce), (prefers-contrast: more) {
  .css-liquid-glass::before { background: rgb(var(--lg-tint-rgb) / .98); backdrop-filter: none; }
}
@media (forced-colors: active) {
  .css-liquid-glass { border: 1px solid canvastext; background: canvas; box-shadow: none; }
  .css-liquid-glass::before, .css-liquid-glass::after { display: none; }
}















.assistant-bubble-glass { --lg-radius: 999px; --lg-blur: 8px; --lg-saturation: 1.28; --lg-tint-rgb: 45 45 45; --lg-tint-alpha: .094; --lg-fallback-alpha: .742; --lg-edge-alpha: .6; --lg-edge-width: .7px; --lg-highlight-alpha: .354; --lg-pointer-alpha: .088; --lg-pointer-x: 34%; --lg-pointer-y: 18%; --lg-pointer-radius: 34%; --lg-shadow-alpha: .214; --lg-displacement: 0; --lg-dispersion: 0; --lg-edge-band: .14; --lg-inner-dark-edge-alpha: .1; --lg-inner-dark-edge-width: .8px; --lg-active-scale: .991; --lg-motion: .42; --lg-ambient-alpha: .115; --lg-noise-alpha: 0; }
.assistant-bubble-glass:is([aria-selected="true"], [aria-pressed="true"], [data-state="selected"], [data-state="open"]) { --lg-tint-alpha: .144; --lg-edge-alpha: .68; }
.assistant-bubble-glass:is(:disabled, [aria-disabled="true"], [data-disabled="true"]) { --lg-motion: 0; --lg-pointer-alpha: 0; cursor: not-allowed; }

























































































@media (prefers-reduced-motion: reduce) {
  *, ::before, ::after { scroll-behavior: auto !important; animation-duration: 0.01ms !important; animation-iteration-count: 1 !important; transition-duration: 0.01ms !important; }
}
@media (forced-colors: active) {
  button:focus-visible, input:focus-visible { outline: highlight solid 2px; box-shadow: none; }
}




































































































.assistant-bubble { position: absolute; z-index: 13; right: 20px; bottom: 84px; display: grid; width: 66px; height: 66px; padding: 5px; place-items: center; border: 0px; border-radius: 50%; outline: none; color: rgb(255, 122, 26); background: transparent; box-shadow: none; appearance: none; cursor: pointer; }
.assistant-bubble:focus-visible { outline: none; }
.assistant-spark { display: block; width: 42px; height: 42px; overflow: visible; pointer-events: none; }
.assistant-spark-orb { width: 56px; height: 56px; overflow: visible; }
.assistant-orb-world { --assistant-mark-scale: .68; transform: scale(var(--assistant-mark-scale)); transform-box: view-box; transform-origin: 50% 50%; animation: 18s linear 0s infinite normal none running assistant-orb-world-idle; will-change: transform; }
.assistant-orb-response { transform-box: view-box; transform-origin: 50% 50%; }
.assistant-orb-sheen { opacity: 0; pointer-events: none; }
.assistant-orb-sheen { transform-origin: 50px 50px; mix-blend-mode: screen; }
.assistant-nebula-haze { transform-origin: 52px 51px; animation: 7s ease-in-out 0s infinite alternate none running assistant-nebula-breathe; }
.assistant-nebula-ribbon { transform-origin: 50px 50px; animation: 6.2s ease-in-out 0s infinite alternate none running assistant-nebula-flow; }
.assistant-orb-halo { opacity: 0.5; animation: 3.8s ease-in-out 0s infinite normal none running assistant-orb-halo; }
.assistant-orb-rim { opacity: 0.94; }
.assistant-bubble:focus-visible .assistant-orb-rim { stroke-width: 2.6; opacity: 1; }
.assistant-mark-depth { filter: blur(0.45px); }
.assistant-mark-glow { animation: 3.2s ease-in-out 0s infinite normal none running assistant-mark-glow; }
.assistant-energy-core { mix-blend-mode: screen; transform-box: fill-box; transform-origin: center center; animation: 3.6s ease-in-out 0s infinite alternate none running assistant-energy-pulse; }
.assistant-energy-cyan { animation-delay: -0.9s; }
.assistant-energy-secondary { animation-delay: -1.8s; }
.assistant-flow-line { stroke-dasharray: 5, 7; animation: 5.5s linear 0s infinite normal none running assistant-flow; }
@keyframes assistant-orb-world-idle { 
  0% { transform: scale(var(--assistant-mark-scale)) rotate(0); }
  100% { transform: scale(var(--assistant-mark-scale)) rotate(360deg); }
}
@keyframes assistant-nebula-breathe { 
  0% { transform: scale(0.92) translate(-2px, 1px); opacity: 0.5; }
  100% { transform: scale(1.08) translate(2px, -1px); opacity: 0.88; }
}
@keyframes assistant-nebula-flow { 
  0% { transform: translate(-4px, 2px) rotate(-4deg); opacity: 0.62; }
  100% { transform: translate(4px, -2px) rotate(4deg); opacity: 0.94; }
}
@keyframes assistant-orb-halo { 
  0%, 100% { opacity: 0.32; stroke-width: 2.4; }
  50% { opacity: 0.7; stroke-width: 3.4; }
}
@keyframes assistant-mark-glow { 
  0%, 100% { opacity: 0.34; }
  50% { opacity: 0.62; }
}
@keyframes assistant-energy-pulse { 
  0% { opacity: 0.58; transform: scale(0.91); }
  100% { opacity: 0.86; transform: scale(1.08); }
}
@keyframes assistant-flow { 
  100% { stroke-dashoffset: -24; }
}







.assistant-bubble:is(:hover, :focus-visible) .spark-gesture, .assistant-spark[data-state="attentive"] .spark-gesture { transform: scale(1.06) rotate(-6deg); }
.assistant-spark[data-state="complete"] { animation: 1.2s ease-out 0s 1 normal both running spark-complete; }
.assistant-spark[data-state="thinking"] .spark-signal { opacity: 0.9; animation: 1.8s linear 0s infinite normal none running spark-transfer; }
.assistant-bubble-hint { position: absolute; right: calc(100% + 12px); top: 50%; transform: translate(4px, -50%); white-space: nowrap; padding: 7px 10px; border-radius: 8px; color: var(--text-body); background: rgb(32, 32, 32); font-size: 12px; opacity: 0; visibility: hidden; pointer-events: none; transition: opacity 0.18s, transform 0.18s, visibility 0.18s; }
.assistant-bubble:is(:hover, :focus-visible) .assistant-bubble-hint { opacity: 1; visibility: visible; transform: translateY(-50%); }



@media (prefers-reduced-motion: reduce) {
  .spark-light-cool, .spark-light-warm, .assistant-spark, .spark-body, .spark-signal, .assistant-spark-orb, .assistant-orb-world, .assistant-nebula-haze, .assistant-nebula-ribbon, .assistant-orb-halo, .assistant-mark-glow, .assistant-energy-core, .assistant-flow-line { animation: auto ease 0s 1 normal none running none !important; }
  .spark-gesture { transition: none; }
}




.organizer-brand .assistant-spark { width: 34px; height: 34px; }






























































































































@media (max-height: 820px) {
  .metric { width: 50px; height: 50px; padding: 6px 3px 5px; }
  .metric-value { font-size: 18px; }
  .metric-label { font-size: 7.5px; }
  .ai-organizer-panel { top: 5%; height: min(650px, 95% - 96px); }
}
@media (prefers-reduced-motion: reduce) {
  .console-memory { transition: none; }
}









@media (prefers-reduced-motion: reduce) {
  :is(.new-note, .action-accent, .action-orange) { transition: none; }
}
@media (forced-colors: active) {
  :is(.new-note, .action-accent, .action-orange) { color: buttontext; background: buttonface; border: 1px solid buttontext; }
  :is(.new-note, .action-accent, .action-orange):focus-visible { outline-color: highlight; }
  .action-accent:disabled { color: graytext; border-color: graytext; }
}













@media (prefers-reduced-motion: reduce) {
  .brand-orientation { transition: none; }
  .brand-assistant.is-active .brand-crop, .brand-assistant.is-active .brand-orientation, .constellation-art.is-active img { animation: auto ease 0s 1 normal none running none; }
}
@media (forced-colors: active) {
  .brand-art, .constellation-art { mix-blend-mode: normal; }
}







.isolated-orb .assistant-bubble { position: relative; inset: auto; width: min(70vmin, 400px); height: min(70vmin, 400px); max-width: 400px; max-height: 400px; }
.isolated-orb .assistant-bubble svg { width: 100%; height: 100%; }
.demo-orb-state-hover .assistant-orb-world, .demo-orb-state-open .assistant-orb-world { animation-play-state: paused; }
.demo-orb-state-hover .assistant-orb-response { transform: rotate(118deg) scale(1.045); }
.demo-orb-state-hover .assistant-orb-halo { opacity: 0.78; stroke-width: 3.2; }
.demo-orb-state-open .assistant-orb-response { transform: rotate(300deg) scale(0.86); opacity: 0.72; }
.demo-orb-state-open .assistant-orb-halo { opacity: 0.24; }
.demo-orb-state-reduced .assistant-orb-world, .demo-orb-state-reduced .assistant-nebula, .demo-orb-state-reduced .assistant-orb-halo, .demo-orb-state-reduced .assistant-mark-glow, .demo-orb-state-reduced .assistant-energy-core, .demo-orb-state-reduced .assistant-flow-line { animation: auto ease 0s 1 normal none running none !important; }
.demo-orb-state-reduced .assistant-orb-world { transform: scale(0.68); opacity: 0.72; }





.sample-row .assistant-bubble { position: relative; inset: auto; }



































































.catalog-assistant .assistant-bubble { position: relative; inset: auto; flex: 0 0 auto; }
